import { useEffect, useMemo, useState, useSyncExternalStore } from "react";
import {
  Home, CalendarDays, CalendarRange, Clock3, BookOpen, ClipboardList, NotebookPen, Sprout,
  Timer, Palette, Archive, Plus, Search, ChevronLeft, ChevronRight, Check, Trash2, Pencil,
  Bell, ImagePlus, Download, Upload, Menu, X, Leaf, CircleHelp, Camera, RotateCcw, ListChecks
} from "lucide-react";
import { createWorker } from "tesseract.js";
import type { Assignment, CalEvent, ClassItem, Goal, Note, Period, Reminder, State, Step } from "./types";
import { classColors, DAYS, defaultState, fileToDataUrl, getState, parseYmd, patchSettings, remove, subscribe, todayYmd, uid, update, upsert, weekdayIndex } from "./store";

type Page = "Home"|"Planner"|"Calendar"|"Timetable"|"Classes"|"Assignments"|"Notes"|"Goals"|"Focus"|"Appearance"|"Backup";
const nav: {name:Page;icon:typeof Home}[] = [
  {name:"Home",icon:Home},{name:"Planner",icon:CalendarRange},{name:"Calendar",icon:CalendarDays},
  {name:"Timetable",icon:Clock3},{name:"Classes",icon:BookOpen},{name:"Assignments",icon:ClipboardList},
  {name:"Notes",icon:NotebookPen},{name:"Goals",icon:Sprout},{name:"Focus",icon:Timer},
  {name:"Appearance",icon:Palette},{name:"Backup",icon:Archive}
];
const dateLabel=(s:string)=>parseYmd(s).toLocaleDateString(undefined,{day:"numeric",month:"short",year:"numeric"});
const blankAssignment=():Assignment=>({id:uid(),title:"",due:todayYmd(),priority:"medium",status:"todo",notes:"",progress:0,steps:[]});
const blankNote=():Note=>({id:uid(),title:"",body:"",topic:"",photos:[],updated:Date.now()});
const blankClass=():ClassItem=>({id:uid(),name:"",color:classColors[0]});
function useData(){return useSyncExternalStore(subscribe,getState,()=>defaultState);}
function Modal({title,close,children}:{title:string;close:()=>void;children:React.ReactNode}){
  return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)close()}}><section className="modal"><div className="modal-head"><h2>{title}</h2><button className="icon-btn" onClick={close} aria-label="Close"><X size={18}/></button></div>{children}</section></div>;
}
function Field({label,children}:{label:string;children:React.ReactNode}){return <label className="field"><span>{label}</span>{children}</label>}
function Empty({title,body,action}:{title:string;body:string;action?:React.ReactNode}){return <div className="empty"><span className="empty-mark"><Leaf size={22}/></span><h3>{title}</h3><p>{body}</p>{action}</div>}

export default function App(){
  const s=useData(); const [page,setPage]=useState<Page>("Home");const [mobileOpen,setMobileOpen]=useState(false);
  const [toast,setToast]=useState("");const [modal,setModal]=useState<React.ReactNode>(null);
  const [month,setMonth]=useState(()=>new Date());const [selected,setSelected]=useState(todayYmd());
  useEffect(()=>{document.documentElement.dataset.theme=s.settings.theme;document.documentElement.dataset.mode=s.settings.mode;document.documentElement.style.setProperty("--accent",s.settings.accent);document.documentElement.dataset.font=s.settings.font;document.documentElement.dataset.size=s.settings.textSize;document.documentElement.style.setProperty("--radius",`${s.settings.radius}px`);if(s.settings.background)document.documentElement.style.setProperty("--background-image",`url("${s.settings.background}")`);else document.documentElement.style.removeProperty("--background-image");},[s.settings]);
  useEffect(()=>{const h=()=>setToast("Browser storage is full. Export a backup and remove some photos.");window.addEventListener("studora-storage-full",h);return()=>window.removeEventListener("studora-storage-full",h)},[]);
  useEffect(()=>{if(!toast)return;const t=window.setTimeout(()=>setToast(""),4000);return()=>clearTimeout(t)},[toast]);
  useEffect(()=>{
    const check=()=>{
      const now=new Date(),key="studora-reminders-shown-"+todayYmd();let shown:string[]=[];
      try{shown=JSON.parse(localStorage.getItem(key)||"[]")}catch{}
      if(!s.settings.notif.enabled)return;
      const due=s.reminders.filter(r=>!r.done&&!shown.includes(r.id)&&r.date===todayYmd()&&Math.abs((parseInt(r.time.slice(0,2))*60+parseInt(r.time.slice(3,5)))-(now.getHours()*60+now.getMinutes()))<=s.settings.notif.lead);
      due.forEach(r=>{setToast(`Reminder: ${r.text}`);if("Notification"in window&&Notification.permission==="granted")try{new Notification("Studora",{body:r.text})}catch{};shown.push(r.id)});
      localStorage.setItem(key,JSON.stringify(shown));
    };
    check();const id=window.setInterval(check,30000);return()=>clearInterval(id);
  },[s.reminders,s.settings.notif]);
  const go=(p:Page)=>{setPage(p);setMobileOpen(false);setModal(null)};
  const title=page==="Home"?(s.settings.name?`A calm day, ${s.settings.name}`:"A calm day starts here"):page;
  return <div className="app-shell">
    <aside className={`sidebar ${mobileOpen?"open":""}`}>
      <div className="brand"><span className="brand-icon"><Leaf size={22}/></span><span><strong>studora</strong><small>your gentle study space</small></span><button className="mobile-close icon-btn" onClick={()=>setMobileOpen(false)}><X size={18}/></button></div>
      <div className="side-label">YOUR SPACE</div><nav>{nav.map(n=><button key={n.name} className={`nav-item ${page===n.name?"active":""}`} onClick={()=>go(n.name)}><n.icon size={18}/><span>{n.name}</span>{n.name==="Assignments"&&s.assignments.some(a=>a.status!=="done"&&a.due<todayYmd())&&<i className="nav-dot"/>}</button>)}</nav>
      <div className="sidebar-bottom"><div className="tiny-leaves"><span>✳</span><span>✿</span><span>❧</span></div><p>A little progress is still progress.</p><small>Saved on this device</small></div>
    </aside>
    {mobileOpen&&<button className="mobile-scrim" onClick={()=>setMobileOpen(false)} aria-label="Close menu"/>}
    <main className="main">
      <header className="topbar"><button className="icon-btn mobile-menu" onClick={()=>setMobileOpen(true)} aria-label="Open menu"><Menu/></button><div className="crumb">STUDORA <span>/</span> {page.toUpperCase()}</div><div className="top-actions"><span className="today-chip"><span className="status-dot"/>{new Date().toLocaleDateString(undefined,{weekday:"short",month:"short",day:"numeric"})}</span><button className="icon-btn" title="Appearance" onClick={()=>go("Appearance")}><Palette size={18}/></button></div></header>
      <div className="content"><div className="page-heading"><div><p className="eyebrow">{page==="Home"?"YOUR STUDY SANCTUARY":"A LITTLE SPACE FOR YOU"}</p><h1>{title}</h1><p className="subheading">{page==="Home"?"Make room for focus, rest, and everything in between.":page==="Calendar"?"Your month, at your own pace.":"Organise gently. You don't have to do it all at once."}</p></div>{page!=="Home"&&<span className="heading-flower">❧</span>}</div>
        {page==="Home"&&<HomePage s={s} go={go} open={setModal}/>}
        {page==="Planner"&&<PlannerPage s={s} go={go}/>}
        {page==="Calendar"&&<CalendarPage s={s} month={month} setMonth={setMonth} selected={selected} setSelected={setSelected} open={setModal}/>}
        {page==="Timetable"&&<TimetablePage s={s} open={setModal} toast={setToast}/>}
        {page==="Classes"&&<ClassesPage s={s} open={setModal}/>}
        {page==="Assignments"&&<AssignmentsPage s={s} open={setModal}/>}
        {page==="Notes"&&<NotesPage s={s} open={setModal} toast={setToast}/>}
        {page==="Goals"&&<GoalsPage s={s} open={setModal}/>}
        {page==="Focus"&&<FocusPage s={s} toast={setToast}/>}
        {page==="Appearance"&&<AppearancePage s={s} toast={setToast}/>}
        {page==="Backup"&&<BackupPage s={s} toast={setToast}/>}
      </div>
      <footer className="footer"><span>Made for your softer, steadier days</span><span>STUDORA · LOCAL FIRST</span></footer>
    </main>
    {modal}
    {toast&&<div className="toast" role="status">{toast}<button onClick={()=>setToast("")} aria-label="Dismiss notification"><X size={14}/></button></div>}
  </div>;
}

function HomePage({s,go,open}:{s:State;go:(p:Page)=>void;open:(v:React.ReactNode)=>void}){
 const today=todayYmd(),todayPeriods=s.periods.filter(p=>p.day===weekdayIndex(new Date())).sort((a,b)=>a.start.localeCompare(b.start));
 const upcoming=s.assignments.filter(a=>a.status!=="done").sort((a,b)=>a.due.localeCompare(b.due)).slice(0,4);
 const events=s.events.filter(e=>e.date>=today).sort((a,b)=>a.date.localeCompare(b.date)).slice(0,3);
 const done=s.assignments.filter(a=>a.status==="done").length;
 return <><div className="welcome-banner"><div><span className="banner-kicker">A NOTE TO SELF</span><h2>Small steps make a lovely journey.</h2><p>Start where you are. Pick one thing, and let that be enough for now.</p><button className="btn btn-light" onClick={()=>open(<AssignmentEditor close={()=>open(null)} />)}><Plus size={16}/> Add an assignment</button></div><div className="banner-art"><div className="sun-disc"/><span className="stem stem-one"/><span className="stem stem-two"/><span className="petal p1"/><span className="petal p2"/><span className="petal p3"/><span className="petal p4"/><span className="banner-leaf">❧</span></div></div>
 <div className="stats-grid"><Stat icon={<ClipboardList/>} label="Still to do" value={s.assignments.length-done} tone="sage"/><Stat icon={<Check/>} label="Completed" value={done} tone="rose"/><Stat icon={<Timer/>} label="Focus today" value={`${s.focusLog[today]||0} min`} tone="lilac"/><Stat icon={<BookOpen/>} label="Your classes" value={s.classes.length} tone="butter"/></div>
 <div className="two-col"><section className="panel"><PanelTitle title="Today's timetable" sub={new Date().toLocaleDateString(undefined,{weekday:"long",month:"long",day:"numeric"})} action="View timetable" click={()=>go("Timetable")}/>{todayPeriods.length?<div className="schedule-list">{todayPeriods.map(p=>{const c=s.classes.find(c=>c.id===p.classId);return <div className="schedule-row" key={p.id}><span className="schedule-time">{p.start}<small>{p.end}</small></span><span className="schedule-line" style={{background:c?.color||"var(--accent)"}}/><div className="schedule-info"><strong>{p.kind==="lunch"?"Lunch":p.kind==="free"?"Free period":c?.name||p.label||"Class"}</strong><small>{p.room||c?.room||"A little learning time"}</small></div></div>})}</div>:<Empty title="A little room in your day" body="Add your classes and weekly periods to see today's timetable here." action={<button className="btn btn-outline" onClick={()=>go("Timetable")}>Set up timetable</button>}/>}</section>
 <section className="panel"><PanelTitle title="Coming up" sub="One thing at a time" action="All assignments" click={()=>go("Assignments")}/>{upcoming.length?<div className="task-list">{upcoming.map(a=><button className="task-row" key={a.id} onClick={()=>open(<AssignmentEditor initial={a} close={()=>open(null)}/>)}><span className={`priority-dot ${a.priority}`}/><span className="task-copy"><strong>{a.title}</strong><small>{dateLabel(a.due)} · {a.status==="doing"?"In progress":"To do"}</small></span><ChevronRight size={17}/></button>)}</div>:<Empty title="Nothing pressing" body="Your task list is clear for now. Enjoy the breathing room." action={<button className="btn btn-outline" onClick={()=>open(<AssignmentEditor close={()=>open(null)}/>)}>Add a task</button>}/>}</section></div>
 <div className="two-col lower"><section className="panel"><PanelTitle title="Dates to remember" sub="Exams and events" action="Open calendar" click={()=>go("Calendar")}/>{events.length?events.map(e=><div className="event-row" key={e.id}><span className={`event-date ${e.kind}`}>{parseYmd(e.date).getDate()}<small>{parseYmd(e.date).toLocaleDateString(undefined,{month:"short"})}</small></span><div><strong>{e.title}</strong><small>{e.kind==="exam"?"Exam":"Event"}{e.time?` · ${e.time}`:""}</small></div></div>):<p className="quiet-note">Add an exam or a special date to keep it in sight.</p>}</section><section className="quote-card"><span className="quote-mark">“</span><p>You are allowed to learn slowly, rest often, and begin again.</p><span>GENTLE REMINDER</span><div className="quote-decoration">❧</div></section></div></>;
}
function Stat({icon,label,value,tone}:{icon:React.ReactNode;label:string;value:string|number;tone:string}){return <div className={`stat-card ${tone}`}><span className="stat-icon">{icon}</span><span className="stat-value">{value}</span><span className="stat-label">{label}</span></div>}
function PanelTitle({title,sub,action,click}:{title:string;sub:string;action?:string;click?:()=>void}){return <div className="panel-title"><div><h2>{title}</h2><p>{sub}</p></div>{action&&<button className="text-link" onClick={click}>{action}<ChevronRight size={15}/></button>}</div>}
function PlannerPage({s,go}:{s:State;go:(p:Page)=>void}){return <div className="planner-grid">{[{title:"Monthly calendar",text:"See the big picture and important dates.",page:"Calendar" as Page,icon:<CalendarDays/>},{title:"Weekly timetable",text:"Your classes, breaks, and free periods.",page:"Timetable" as Page,icon:<Clock3/>},{title:"Assignment tracker",text:"Deadlines, priorities, and tiny next steps.",page:"Assignments" as Page,icon:<ListChecks/>},{title:"Notes library",text:"Keep your thoughts and revision together.",page:"Notes" as Page,icon:<NotebookPen/>},{title:"Goals and habits",text:"Build routines gently, one check-in at a time.",page:"Goals" as Page,icon:<Sprout/>},{title:"Focus room",text:"A quiet timer for one thing at a time.",page:"Focus" as Page,icon:<Timer/>}].map(x=><button className="planner-card" key={x.title} onClick={()=>go(x.page)}><span className="planner-icon">{x.icon}</span><h2>{x.title}</h2><p>{x.text}</p><span className="planner-count">{x.page==="Assignments"?s.assignments.length:x.page==="Notes"?s.notes.length:x.page==="Goals"?s.goals.length:""} {x.page==="Assignments"?"tasks":x.page==="Notes"?"notes":x.page==="Goals"?"items":""}</span><span className="card-arrow"><ChevronRight/></span></button>)}</div>}
function CalendarPage({s,month,setMonth,selected,setSelected,open}:{s:State;month:Date;setMonth:(d:Date)=>void;selected:string;setSelected:(d:string)=>void;open:(v:React.ReactNode)=>void}){
 const [view,setView]=useState<"month"|"week"|"day"|"agenda">("month");const [filter,setFilter]=useState("all");
 const y=month.getFullYear(),m=month.getMonth(),first=new Date(y,m,1),offset=weekdayIndex(first),days=new Date(y,m+1,0).getDate();
 const items=(date:string)=>[...s.events.filter(e=>e.date===date&& (filter==="all"||filter===e.kind)).map(e=>({id:e.id,title:e.title,kind:e.kind==="exam"?"Exam":"Event",date})),...s.assignments.filter(a=>a.due===date&&a.status!=="done"&&(filter==="all"||filter==="assignment")).map(a=>({id:a.id,title:a.title,kind:"Assignment",date}))];
 const selectedItems=items(selected);
 const cells=Array.from({length:Math.ceil((offset+days)/7)*7},(_,i)=>{const n=i-offset+1;return n>0&&n<=days?new Date(y,m,n):null});
 const goMonth=(n:number)=>setMonth(new Date(y,m+n,1));
 return <><div className="panel calendar-panel"><div className="calendar-toolbar"><div className="view-switch">{(["month","week","day","agenda"] as const).map(v=><button key={v} className={view===v?"selected":""} onClick={()=>setView(v)}>{v[0].toUpperCase()+v.slice(1)}</button>)}</div><div className="month-controls"><button className="icon-btn" onClick={()=>goMonth(-1)} aria-label="Previous month"><ChevronLeft/></button><h2>{month.toLocaleDateString(undefined,{month:"long",year:"numeric"})}</h2><button className="icon-btn" onClick={()=>goMonth(1)} aria-label="Next month"><ChevronRight/></button><button className="btn btn-outline btn-small" onClick={()=>{setMonth(new Date());setSelected(todayYmd())}}>Today</button></div><select value={filter} onChange={e=>setFilter(e.target.value)} aria-label="Filter calendar"><option value="all">All items</option><option value="exam">Exams</option><option value="event">Events</option><option value="assignment">Assignments</option></select></div>
 {view==="month"?<><div className="calendar-grid weekdays">{DAYS.map(d=><div key={d}>{d.slice(0,3)}</div>)}</div><div className="calendar-grid">{cells.map((d,i)=>{if(!d)return <div className="calendar-cell muted-cell" key={`empty${i}`}/>;const ds=todayYmd(d),its=items(ds);return <button key={ds} className={`calendar-cell ${ds===todayYmd()?"is-today":""} ${selected===ds?"is-selected":""}`} onClick={()=>setSelected(ds)}><span className="day-number">{d.getDate()}</span>{its.slice(0,2).map(it=><span className={`calendar-event ${it.kind.toLowerCase()}`} key={it.id}>{it.title}</span>)}{its.length>2&&<small>+{its.length-2} more</small>}</button>})}</div></>:<div className="calendar-list-view">{(view==="day"?[selected]:view==="week"?Array.from({length:7},(_,i)=>{const d=parseYmd(selected);d.setDate(d.getDate()-weekdayIndex(d)+i);return todayYmd(d)}):Array.from({length:days},(_,i)=>todayYmd(new Date(y,m,i+1)))).map(ds=><div className="agenda-day" key={ds}><strong>{dateLabel(ds)}</strong>{items(ds).map(it=><div className="agenda-item" key={it.id}><span className={`priority-dot ${it.kind==="Exam"?"high":"medium"}`}/><span>{it.title}</span><small>{it.kind}</small></div>)}</div>)}</div>}
 <div className="selected-day"><div className="selected-date"><span>SELECTED DATE</span><h3>{dateLabel(selected)}</h3></div><button className="btn btn-primary" onClick={()=>open(<EventEditor date={selected} close={()=>open(null)}/>)}><Plus size={16}/> Add date</button></div>{selectedItems.length?selectedItems.map(it=><div className="simple-row" key={it.id}><span className="priority-dot medium"/><span>{it.title}</span><small>{it.kind}</small></div>):<p className="quiet-note">Nothing on this date yet. Keep it open, or add something to remember.</p>}</div></>;
}
function ClassesPage({s,open}:{s:State;open:(v:React.ReactNode)=>void}){return <><div className="toolbar-row"><p className="muted-copy">{s.classes.length} {s.classes.length===1?"class":"classes"} in your school week</p><button className="btn btn-primary" onClick={()=>open(<ClassEditor close={()=>open(null)}/>)}><Plus size={16}/> Add class</button></div>{s.classes.length?<div className="class-grid">{s.classes.map(c=><div className="class-card" key={c.id}><span className="class-swatch" style={{background:c.color}}/><div className="class-main"><h3>{c.name}</h3><p>{c.teacher||"Teacher not added"}{c.room?` · ${c.room}`:""}</p></div><button className="icon-btn" aria-label={`Edit ${c.name}`} onClick={()=>open(<ClassEditor initial={c} close={()=>open(null)}/>)}><Pencil size={16}/></button><button className="icon-btn danger" aria-label={`Delete ${c.name}`} onClick={()=>{if(confirm(`Delete ${c.name} and its timetable periods?`)){remove("classes",c.id);update(st=>({...st,periods:st.periods.filter(p=>p.classId!==c.id),assignments:st.assignments.map(a=>a.classId===c.id?{...a,classId:undefined}:a),notes:st.notes.map(n=>n.classId===c.id?{...n,classId:undefined}:n)}))}}}><Trash2 size={16}/></button></div>)}</div>:<Empty title="Your classes, your colours" body="Add your subjects, teachers and rooms to begin building your timetable." action={<button className="btn btn-primary" onClick={()=>open(<ClassEditor close={()=>open(null)}/>)}><Plus size={16}/> Add your first class</button>}/>}</>}
function ClassEditor({initial,close}:{initial?:ClassItem;close:()=>void}){const [v,setV]=useState<ClassItem>(initial||blankClass());return <Modal title={initial?"Edit class":"Add a class"} close={close}><form onSubmit={e=>{e.preventDefault();if(!v.name.trim())return;upsert("classes",{...v,name:v.name.trim()});close()}}><Field label="Class name"><input autoFocus required value={v.name} onChange={e=>setV({...v,name:e.target.value})} placeholder="e.g. Biology"/></Field><div className="form-grid"><Field label="Teacher"><input value={v.teacher||""} onChange={e=>setV({...v,teacher:e.target.value})} placeholder="Optional"/></Field><Field label="Room"><input value={v.room||""} onChange={e=>setV({...v,room:e.target.value})} placeholder="Optional"/></Field></div><Field label="Class colour"><div className="color-options">{classColors.map(c=><button type="button" key={c} className={`color-dot ${v.color===c?"chosen":""}`} style={{background:c}} onClick={()=>setV({...v,color:c})} aria-label={`Choose ${c}`}/>)}</div></Field><FormActions close={close}/></form></Modal>}
function FormActions({close}:{close:()=>void}){return <div className="form-actions"><button type="button" className="btn btn-outline" onClick={close}>Cancel</button><button className="btn btn-primary" type="submit">Save</button></div>}
function AssignmentEditor({initial,close}:{initial?:Assignment;close:()=>void}){const [v,setV]=useState<Assignment>(initial?{...initial,steps:[...initial.steps]}:blankAssignment());const [stepText,setStepText]=useState("");const s=useData();return <Modal title={initial?"Edit assignment":"Add an assignment"} close={close}><form onSubmit={e=>{e.preventDefault();if(!v.title.trim())return;upsert("assignments",{...v,title:v.title.trim(),progress:v.steps.length?Math.round(v.steps.filter(x=>x.done).length/v.steps.length*100):v.progress});close()}}><Field label="What needs doing?"><input autoFocus required value={v.title} onChange={e=>setV({...v,title:e.target.value})} placeholder="e.g. Biology lab report"/></Field><div className="form-grid"><Field label="Due date"><input type="date" required value={v.due} onChange={e=>setV({...v,due:e.target.value})}/></Field><Field label="Class"><select value={v.classId||""} onChange={e=>setV({...v,classId:e.target.value||undefined})}><option value="">No class</option>{s.classes.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></Field><Field label="Priority"><select value={v.priority} onChange={e=>setV({...v,priority:e.target.value as Assignment["priority"]})}><option value="low">Low</option><option value="medium">Medium</option><option value="high">High</option></select></Field><Field label="Status"><select value={v.status} onChange={e=>setV({...v,status:e.target.value as Assignment["status"]})}><option value="todo">To do</option><option value="doing">In progress</option><option value="done">Completed</option></select></Field></div><Field label="Notes"><textarea rows={3} value={v.notes} onChange={e=>setV({...v,notes:e.target.value})} placeholder="Anything to remember…"/></Field><Field label="Small steps"><div className="inline-add"><input value={stepText} onChange={e=>setStepText(e.target.value)} placeholder="Break it into a tiny step"/><button className="btn btn-outline" type="button" onClick={()=>{if(stepText.trim()){setV({...v,steps:[...v.steps,{id:uid(),text:stepText.trim(),done:false}]});setStepText("")}}}><Plus size={15}/></button></div>{v.steps.map(st=><label className="check-row" key={st.id}><input type="checkbox" checked={st.done} onChange={e=>setV({...v,steps:v.steps.map(x=>x.id===st.id?{...x,done:e.target.checked}:x)})}/>{st.text}<button type="button" className="mini-delete" onClick={()=>setV({...v,steps:v.steps.filter(x=>x.id!==st.id)})}><X size={13}/></button></label>)}</Field><FormActions close={close}/></form></Modal>}
function AssignmentsPage({s,open}:{s:State;open:(v:React.ReactNode)=>void}){const [q,setQ]=useState("");const [status,setStatus]=useState("all");const [priority,setPriority]=useState("all");const [sort,setSort]=useState("due");const filtered=s.assignments.filter(a=>a.title.toLowerCase().includes(q.toLowerCase())&&(status==="all"||a.status===status)&&(priority==="all"||a.priority===priority)).sort((a,b)=>sort==="due"?a.due.localeCompare(b.due):a.title.localeCompare(b.title));return <><div className="toolbar-row"><p className="muted-copy">{s.assignments.filter(a=>a.status!=="done").length} things in progress — one step at a time.</p><button className="btn btn-primary" onClick={()=>open(<AssignmentEditor close={()=>open(null)}/>)}><Plus size={16}/> Add assignment</button></div><div className="filter-bar"><label className="search-field"><Search size={16}/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Find an assignment…"/></label><select value={status} onChange={e=>setStatus(e.target.value)}><option value="all">All statuses</option><option value="todo">To do</option><option value="doing">In progress</option><option value="done">Completed</option></select><select value={priority} onChange={e=>setPriority(e.target.value)}><option value="all">All priorities</option><option value="high">High</option><option value="medium">Medium</option><option value="low">Low</option></select><select value={sort} onChange={e=>setSort(e.target.value)}><option value="due">Sort by due date</option><option value="title">Sort by title</option></select></div>{filtered.length?<div className="assignment-list">{filtered.map(a=>{const c=s.classes.find(x=>x.id===a.classId);return <article className={`assignment-card ${a.status==="done"?"is-done":""}`} key={a.id}><div className="assignment-check"><input type="checkbox" checked={a.status==="done"} aria-label={`Mark ${a.title} completed`} onChange={e=>upsert("assignments",{...a,status:e.target.checked?"done":"todo"})}/></div><div className="assignment-content"><div className="assignment-title-row"><h3>{a.title}</h3><span className={`pill ${a.priority}`}>{a.priority}</span></div><p>{dateLabel(a.due)}{c?` · ${c.name}`:""}{a.status==="doing"?" · In progress":""}</p>{a.notes&&<p className="assignment-notes">{a.notes}</p>}{a.steps.length>0&&<div className="progress-wrap"><div className="progress-track"><span style={{width:`${Math.round(a.steps.filter(x=>x.done).length/a.steps.length*100)}%`}}/></div><small>{a.steps.filter(x=>x.done).length}/{a.steps.length} steps</small></div>}</div><button className="icon-btn" onClick={()=>open(<AssignmentEditor initial={a} close={()=>open(null)}/>)} aria-label="Edit assignment"><Pencil size={16}/></button><button className="icon-btn danger" onClick={()=>{if(confirm("Delete this assignment?"))remove("assignments",a.id)}} aria-label="Delete assignment"><Trash2 size={16}/></button></article>})}</div>:<Empty title="No matching assignments" body="Try another filter, or add a task when you are ready." action={<button className="btn btn-primary" onClick={()=>open(<AssignmentEditor close={()=>open(null)}/>)}><Plus size={16}/> Add assignment</button>}/>}</>}
function EventEditor({date,close}:{date:string;close:()=>void}){const [v,setV]=useState<CalEvent>({id:uid(),date,title:"",kind:"event"});const s=useData();return <Modal title="Add a calendar date" close={close}><form onSubmit={e=>{e.preventDefault();if(v.title.trim())upsert("events",{...v,title:v.title.trim()});close()}}><Field label="Title"><input required autoFocus value={v.title} onChange={e=>setV({...v,title:e.target.value})} placeholder="e.g. Chemistry exam"/></Field><div className="form-grid"><Field label="Date"><input type="date" value={v.date} onChange={e=>setV({...v,date:e.target.value})}/></Field><Field label="Type"><select value={v.kind} onChange={e=>setV({...v,kind:e.target.value as CalEvent["kind"]})}><option value="event">Event</option><option value="exam">Exam</option></select></Field><Field label="Time (optional)"><input type="time" value={v.time||""} onChange={e=>setV({...v,time:e.target.value})}/></Field><Field label="Class (optional)"><select value={v.classId||""} onChange={e=>setV({...v,classId:e.target.value||undefined})}><option value="">No class</option>{s.classes.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></Field></div><FormActions close={close}/></form></Modal>}
function TimetablePage({s,open,toast}:{s:State;open:(v:React.ReactNode)=>void;toast:(v:string)=>void}){
 const [day,setDay]=useState(weekdayIndex(new Date()));const [scanning,setScanning]=useState(false);const [staged,setStaged]=useState<Partial<Period>[]>([]);const [showReview,setShowReview]=useState(false);
 const periods=s.periods.filter(p=>p.day===day).sort((a,b)=>a.start.localeCompare(b.start));
 const scan=async(file:File)=>{setScanning(true);try{const worker=await createWorker("eng");const result=await worker.recognize(file);await worker.terminate();const lines=result.data.text.split(/\n/).map(x=>x.trim()).filter(Boolean);const times=/(\d{1,2}:\d{2})\s*(?:-|–|to)\s*(\d{1,2}:\d{2})/i;const found:Partial<Period>[]=[];for(const line of lines){const match=line.match(times);if(match){const name=line.replace(match[0],"").replace(/^[\s:|-]+|[\s:|-]+$/g,"").trim();found.push({id:uid(),day,start:match[1].padStart(5,"0"),end:match[2].padStart(5,"0"),kind:/lunch/i.test(name)?"lunch":"class",label:name||"Review class name"});}}if(!found.length)throw new Error("No time ranges found");setStaged(found);setShowReview(true)}catch{toast("Couldn't read clear class times from that image. You can still add periods manually.");}finally{setScanning(false)}};
 return <><div className="panel"><div className="day-tabs">{DAYS.map((d,i)=><button className={day===i?"selected":""} key={d} onClick={()=>setDay(i)}>{d.slice(0,3)}</button>)}</div><div className="toolbar-row timetable-tools"><p className="muted-copy">{DAYS[day]} · {periods.length} periods</p><div className="button-row"><label className="btn btn-outline upload-btn"><Camera size={16}/>{scanning?"Reading image…":"Scan timetable photo"}<input type="file" accept="image/*" disabled={scanning} onChange={e=>{const f=e.target.files?.[0];if(f)void scan(f);e.currentTarget.value=""}}/></label><button className="btn btn-primary" onClick={()=>open(<PeriodEditor day={day} close={()=>open(null)}/>)}><Plus size={16}/> Add period</button></div></div>{periods.length?<div className="timetable-list">{periods.map(p=>{const c=s.classes.find(x=>x.id===p.classId);return <div className="period-row" key={p.id}><div className="period-time">{p.start}<span>{p.end}</span></div><span className="period-bar" style={{background:c?.color||"var(--accent)"}}/><div className="period-details"><strong>{p.kind==="lunch"?"Lunch":p.kind==="free"?"Free period":c?.name||p.label||"Class"}</strong><small>{p.room||c?.room||"No room added"}</small></div><button className="icon-btn" onClick={()=>open(<PeriodEditor day={day} initial={p} close={()=>open(null)}/>)}><Pencil size={15}/></button><button className="icon-btn danger" onClick={()=>{if(confirm("Remove this period?"))remove("periods",p.id)}}><Trash2 size={15}/></button></div>})}</div>:<Empty title="A blank page for your week" body="Add your classes, lunch and free periods. Each day can have its own schedule." action={<button className="btn btn-primary" onClick={()=>open(<PeriodEditor day={day} close={()=>open(null)}/>)}><Plus size={16}/> Add a period</button>}/>}</div><div className="hint-card"><CircleHelp size={18}/><p><strong>Photo tip</strong><br/>Choose a clear timetable image. Studora looks for time ranges and suggests period names; review every result before saving. OCR works best with printed, well-lit schedules.</p></div>{showReview&&<Modal title="Review scanned periods" close={()=>setShowReview(false)}><p className="muted-copy">Please check the times and names. These are suggestions from the image, not guaranteed to be correct.</p>{staged.map((p,i)=><div className="form-grid scan-row" key={p.id}><Field label="Start"><input type="time" value={p.start||"08:00"} onChange={e=>setStaged(staged.map((x,j)=>j===i?{...x,start:e.target.value}:x))}/></Field><Field label="End"><input type="time" value={p.end||"08:45"} onChange={e=>setStaged(staged.map((x,j)=>j===i?{...x,end:e.target.value}:x))}/></Field><Field label="Detected name"><input value={p.label||""} onChange={e=>setStaged(staged.map((x,j)=>j===i?{...x,label:e.target.value}:x))}/></Field></div>)}<div className="form-actions"><button className="btn btn-outline" onClick={()=>setShowReview(false)}>Cancel</button><button className="btn btn-primary" onClick={()=>{staged.forEach(p=>upsert("periods",{id:p.id||uid(),day,start:p.start||"08:00",end:p.end||"08:45",kind:p.kind||"class",label:p.label||"Class"}));setShowReview(false);toast("Reviewed periods saved.")}}>Save reviewed periods</button></div></Modal>}</>;
}
function PeriodEditor({day,initial,close}:{day:number;initial?:Period;close:()=>void}){const s=useData();const [v,setV]=useState<Period>(initial||{id:uid(),day,start:"09:00",end:"09:45",kind:"class"});return <Modal title={initial?"Edit period":"Add a period"} close={close}><form onSubmit={e=>{e.preventDefault();if(v.start>=v.end)return;upsert("periods",v);close()}}><Field label="Day"><select value={v.day} onChange={e=>setV({...v,day:Number(e.target.value)})}>{DAYS.map((d,i)=><option key={d} value={i}>{d}</option>)}</select></Field><div className="form-grid"><Field label="Start"><input type="time" required value={v.start} onChange={e=>setV({...v,start:e.target.value})}/></Field><Field label="End"><input type="time" required value={v.end} onChange={e=>setV({...v,end:e.target.value})}/></Field></div><Field label="Period type"><select value={v.kind} onChange={e=>setV({...v,kind:e.target.value as Period["kind"]})}><option value="class">Class</option><option value="lunch">Lunch</option><option value="free">Free period</option></select></Field>{v.kind==="class"?<Field label="Class"><select value={v.classId||""} onChange={e=>setV({...v,classId:e.target.value||undefined})}><option value="">Custom label</option>{s.classes.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></Field>:null}<Field label="Label / room"><input value={v.label||""} onChange={e=>setV({...v,label:e.target.value})} placeholder="Optional label"/></Field><Field label="Room"><input value={v.room||""} onChange={e=>setV({...v,room:e.target.value})} placeholder="Optional"/></Field><FormActions close={close}/></form></Modal>}
function NotesPage({s,open,toast}:{s:State;open:(v:React.ReactNode)=>void;toast:(v:string)=>void}){const [q,setQ]=useState("");const list=s.notes.filter(n=>`${n.title} ${n.body} ${n.topic}`.toLowerCase().includes(q.toLowerCase())).sort((a,b)=>b.updated-a.updated);return <><div className="toolbar-row"><p className="muted-copy">Your own words, ideas, and revision notes.</p><button className="btn btn-primary" onClick={()=>open(<NoteEditor close={()=>open(null)} toast={toast}/>)}><Plus size={16}/> New note</button></div><label className="search-field notes-search"><Search size={16}/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Search notes and topics…"/></label>{list.length?<div className="notes-grid">{list.map(n=><article className="note-card" key={n.id}><div className="note-top"><span className="note-topic">{n.topic||"QUICK NOTE"}</span><div><button className="icon-btn" onClick={()=>open(<NoteEditor initial={n} close={()=>open(null)} toast={toast}/>)} aria-label="Edit note"><Pencil size={15}/></button><button className="icon-btn danger" onClick={()=>{if(confirm("Delete this note?"))remove("notes",n.id)}} aria-label="Delete note"><Trash2 size={15}/></button></div></div><h3>{n.title}</h3><p className="note-body">{n.body||"No note text yet."}</p>{n.photos.length>0&&<div className="note-photos">{n.photos.map((p,i)=><img key={i} src={p} alt={`Attached note ${i+1}`}/>)}</div>}<small>Updated {new Date(n.updated).toLocaleDateString()}</small></article>)}</div>:<Empty title="A home for your notes" body="Save class notes, revision reminders, or any little thought you want to keep." action={<button className="btn btn-primary" onClick={()=>open(<NoteEditor close={()=>open(null)} toast={toast}/>)}><Plus size={16}/> Write a note</button>}/>}</>}
function NoteEditor({initial,close,toast}:{initial?:Note;close:()=>void;toast:(v:string)=>void}){const [v,setV]=useState<Note>(initial?{...initial,photos:[...initial.photos]}:blankNote());const s=useData();return <Modal title={initial?"Edit note":"Write a note"} close={close}><form onSubmit={e=>{e.preventDefault();if(!v.title.trim())return;upsert("notes",{...v,title:v.title.trim(),updated:Date.now()});close()}}><Field label="Title"><input autoFocus required value={v.title} onChange={e=>setV({...v,title:e.target.value})} placeholder="A useful title"/></Field><div className="form-grid"><Field label="Topic"><input value={v.topic} onChange={e=>setV({...v,topic:e.target.value})} placeholder="e.g. Cell biology"/></Field><Field label="Class"><select value={v.classId||""} onChange={e=>setV({...v,classId:e.target.value||undefined})}><option value="">No class</option>{s.classes.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></Field></div><Field label="Your notes"><textarea rows={7} value={v.body} onChange={e=>setV({...v,body:e.target.value})} placeholder="Write freely…"/></Field><Field label="Attach handwritten notes or photos"><label className="btn btn-outline upload-btn"><ImagePlus size={16}/> Choose photos<input type="file" accept="image/*" multiple onChange={async e=>{const fs=Array.from(e.target.files||[]);try{const urls=await Promise.all(fs.slice(0,4-v.photos.length).map(f=>fileToDataUrl(f,1000,.72)));setV({...v,photos:[...v.photos,...urls]})}catch{toast("Couldn't load that image.")}e.currentTarget.value=""}}/></label><div className="note-photos">{v.photos.map((p,i)=><div className="photo-thumb" key={i}><img src={p} alt={`Attachment ${i+1}`}/><button type="button" onClick={()=>setV({...v,photos:v.photos.filter((_,j)=>j!==i)})}>Remove</button></div>)}</div></Field><FormActions close={close}/></form></Modal>}
function GoalsPage({s,open}:{s:State;open:(v:React.ReactNode)=>void}){const today=todayYmd();return <><div className="toolbar-row"><p className="muted-copy">No streak pressure. Showing up when you can is enough.</p><button className="btn btn-primary" onClick={()=>open(<GoalEditor close={()=>open(null)}/>)}><Plus size={16}/> Add goal</button></div>{s.goals.length?<div className="goals-grid">{s.goals.map(g=>{const checked=g.checks.includes(today);return <article className="goal-card" key={g.id}><div className="goal-head"><span className="planner-icon"><Sprout/></span><span className="note-topic">{g.kind==="habit"?"HABIT":"GOAL"}</span><button className="icon-btn danger" onClick={()=>{if(confirm("Delete this goal?"))remove("goals",g.id)}} aria-label="Delete goal"><Trash2 size={15}/></button></div><h3>{g.title}</h3><p>{g.kind==="habit"?"A small habit, at your pace.":`A goal with ${g.target} gentle steps.`}</p><button className={`checkin-btn ${checked?"checked":""}`} onClick={()=>upsert("goals",{...g,checks:checked?g.checks.filter(d=>d!==today):[...g.checks,today]})}>{checked?<Check size={16}/>:<Plus size={16}/>} {checked?"Checked in today":"Check in today"}</button><div className="goal-footer"><span>{g.checks.length} check-ins in total</span><button className="text-link" onClick={()=>open(<GoalEditor initial={g} close={()=>open(null)}/>)}><Pencil size={14}/> Edit</button></div></article>})}</div>:<Empty title="Make space for a small goal" body="Read for ten minutes, practise a skill, or take a mindful break. Your goals belong to you." action={<button className="btn btn-primary" onClick={()=>open(<GoalEditor close={()=>open(null)}/>)}><Plus size={16}/> Add a goal</button>}/>}</>}
function GoalEditor({initial,close}:{initial?:Goal;close:()=>void}){const [title,setTitle]=useState(initial?.title||"");const [kind,setKind]=useState<Goal["kind"]>(initial?.kind||"habit");const [target,setTarget]=useState(initial?.target||7);return <Modal title={initial?"Edit goal":"Add a goal"} close={close}><form onSubmit={e=>{e.preventDefault();if(title.trim())upsert("goals",{id:initial?.id||uid(),title:title.trim(),kind,target,checks:initial?.checks||[]});close()}}><Field label="Goal or habit"><input autoFocus required value={title} onChange={e=>setTitle(e.target.value)} placeholder="e.g. Read a little each day"/></Field><Field label="Type"><select value={kind} onChange={e=>setKind(e.target.value as Goal["kind"])}><option value="habit">Habit</option><option value="goal">Goal</option></select></Field><Field label="A gentle target (days / steps)"><input type="number" min="1" max="365" value={target} onChange={e=>setTarget(Number(e.target.value))}/></Field><FormActions close={close}/></form></Modal>}
function FocusPage({s,toast}:{s:State;toast:(v:string)=>void}){const [minutes,setMinutes]=useState(s.settings.focusMin);const [remaining,setRemaining]=useState(s.settings.focusMin*60);const [running,setRunning]=useState(false);const [mode,setMode]=useState<"focus"|"break">("focus");useEffect(()=>{if(!running)return;const id=window.setInterval(()=>setRemaining(r=>{if(r<=1){setRunning(false);if(mode==="focus"){const today=todayYmd();update(st=>({...st,focusLog:{...st.focusLog,[today]:(st.focusLog[today]||0)+minutes}}));toast("Focus session complete. Take a gentle break.");}else toast("Break time is over. Ready when you are.");return 0;}return r-1}),1000);return()=>clearInterval(id)},[running,mode,minutes,toast]);const total=mode==="focus"?minutes*60:s.settings.breakMin*60;const mm=String(Math.floor(remaining/60)).padStart(2,"0"),ss=String(remaining%60).padStart(2,"0");const pct=total?((total-remaining)/total)*100:0;return <div className="focus-layout"><section className="focus-panel"><p className="eyebrow">A LITTLE FOCUS TIME</p><div className="focus-mode"><button className={mode==="focus"?"selected":""} onClick={()=>{setMode("focus");setRunning(false);setRemaining(minutes*60)}}>Focus</button><button className={mode==="break"?"selected":""} onClick={()=>{setMode("break");setRunning(false);setRemaining(s.settings.breakMin*60)}}>Break</button></div><div className="timer-ring" style={{"--progress":`${pct}%`} as React.CSSProperties}><div className="timer-inner"><span>{mm}:{ss}</span><small>{mode==="focus"?"ONE THING AT A TIME":"REST A LITTLE"}</small></div></div>{mode==="focus"&&<div className="duration-control"><span>Session length</span><div>{[15,25,30,45,60].map(n=><button key={n} className={minutes===n?"selected":""} onClick={()=>{setMinutes(n);setRemaining(n*60);setRunning(false)}}>{n}m</button>)}</div></div>}<div className="timer-actions"><button className="btn btn-primary" onClick={()=>{if(remaining===0)setRemaining(total);setRunning(!running)}}>{running?"Pause":remaining===0?"Start again":"Start focus"}</button><button className="btn btn-outline" onClick={()=>{setRunning(false);setRemaining(total)}}><RotateCcw size={15}/> Reset</button></div><p className="quiet-note">You can pause or stop at any time. Rest is part of the work.</p></section><section className="panel focus-side"><PanelTitle title="Your focus garden" sub="Minutes you've made space for"/><div className="focus-total">{s.focusLog[todayYmd()]||0}<span>minutes today</span></div><div className="focus-flower">❧</div><p className="muted-copy">Every quiet minute counts, even if it is just one.</p><Field label="Default focus duration"><select value={s.settings.focusMin} onChange={e=>patchSettings({focusMin:Number(e.target.value)})}>{[15,20,25,30,45,60].map(n=><option key={n} value={n}>{n} minutes</option>)}</select></Field><Field label="Default break duration"><select value={s.settings.breakMin} onChange={e=>patchSettings({breakMin:Number(e.target.value)})}>{[3,5,10,15].map(n=><option key={n} value={n}>{n} minutes</option>)}</select></Field></section></div>}
function AppearancePage({s,toast}:{s:State;toast:(v:string)=>void}){const themes=[["sage","#819b7a","#e8eee3"],["oatmeal","#b7a68b","#f1eadc"],["rose","#c58f9a","#f3e4e7"],["lilac","#a99bc8","#ece7f5"],["butter","#c7a95e","#f6efcf"],["blue","#8ba9c5","#e3edf5"],["neutral","#8c8d86","#e9e9e3"]] as const;const upload=async(kind:"avatar"|"background",file?:File)=>{if(!file)return;if(file.size>12*1024*1024){toast("Please choose an image smaller than 12 MB.");return}try{patchSettings({[kind]:await fileToDataUrl(file,kind==="avatar"?500:1400,.78)});toast("Image saved on this device.")}catch{toast("Couldn't load that image.")}};return <div className="settings-layout"><section className="panel settings-panel"><PanelTitle title="Your colour story" sub="Choose a palette that feels like you."/><div className="theme-grid">{themes.map(([name,accent,bg])=><button key={name} className={`theme-choice ${s.settings.theme===name?"chosen":""}`} onClick={()=>patchSettings({theme:name as typeof s.settings.theme,accent})}><span className="theme-swatch" style={{background:bg}}><i style={{background:accent}}/><i style={{background:"#d5b2ad"}}/><i style={{background:"#d8c9e7"}}/></span><span>{name[0].toUpperCase()+name.slice(1)}</span>{s.settings.theme===name&&<Check size={15}/>}</button>)}</div><div className="setting-row"><div><strong>Light or dark</strong><small>Pick the mood for your study space.</small></div><div className="segmented"><button className={s.settings.mode==="light"?"selected":""} onClick={()=>patchSettings({mode:"light"})}>Light</button><button className={s.settings.mode==="dark"?"selected":""} onClick={()=>patchSettings({mode:"dark"})}>Dark</button></div></div><div className="setting-row"><div><strong>Accent colour</strong><small>Personalise buttons and highlights.</small></div><input className="color-input" type="color" value={s.settings.accent} onChange={e=>patchSettings({accent:e.target.value})}/></div><Field label="Font"><select value={s.settings.font} onChange={e=>patchSettings({font:e.target.value as typeof s.settings.font})}><option value="dm">DM Sans</option><option value="nunito">Nunito-style rounded</option><option value="serif">Soft serif headings</option><option value="system">System default</option></select></Field><div className="form-grid"><Field label="Text size"><select value={s.settings.textSize} onChange={e=>patchSettings({textSize:e.target.value as typeof s.settings.textSize})}><option value="sm">Small</option><option value="md">Medium</option><option value="lg">Large</option></select></Field><Field label="Corner roundness"><input type="range" min="8" max="28" value={s.settings.radius} onChange={e=>patchSettings({radius:Number(e.target.value)})}/></Field></div><Field label="Spacing"><select value={s.settings.spacing} onChange={e=>patchSettings({spacing:e.target.value as typeof s.settings.spacing})}><option value="compact">Compact</option><option value="comfortable">Comfortable</option><option value="spacious">Spacious</option></select></Field></section><section className="panel settings-panel"><PanelTitle title="Make it yours" sub="Your images stay in this browser."/><div className="profile-preview">{s.settings.avatar?<img src={s.settings.avatar} alt="Your profile"/>:<span><Leaf size={28}/></span>}<div><strong>{s.settings.name||"Your profile"}</strong><small>Little by little, you grow.</small></div></div><Field label="Your name"><input value={s.settings.name} onChange={e=>patchSettings({name:e.target.value})} placeholder="What should Studora call you?"/></Field><Field label="Profile picture"><label className="btn btn-outline upload-btn"><ImagePlus size={16}/> Choose image<input type="file" accept="image/*" onChange={e=>void upload("avatar",e.target.files?.[0])}/></label></Field>{s.settings.avatar&&<button className="text-link" onClick={()=>patchSettings({avatar:undefined})}>Remove profile image</button>}<Field label="Background photo"><label className="btn btn-outline upload-btn"><ImagePlus size={16}/> Choose background<input type="file" accept="image/*" onChange={e=>void upload("background",e.target.files?.[0])}/></label></Field>{s.settings.background&&<><div className="background-preview" style={{backgroundImage:`url("${s.settings.background}")`}}/><button className="text-link" onClick={()=>patchSettings({background:undefined})}>Remove background</button></>}<div className="hint-card"><Bell size={18}/><p><strong>Gentle reminders</strong><br/>When enabled, Studora checks reminders while this page is open. Browser notifications are optional and may not appear if the browser is closed.</p></div><div className="setting-row"><div><strong>Enable reminders</strong><small>Check scheduled reminders while Studora is open.</small></div><input type="checkbox" checked={s.settings.notif.enabled} onChange={e=>patchSettings({notif:{...s.settings.notif,enabled:e.target.checked}})}/></div><Field label="Reminder lead time"><select value={s.settings.notif.lead} onChange={e=>patchSettings({notif:{...s.settings.notif,lead:Number(e.target.value)}})}>{[0,5,10,15,30,60].map(n=><option key={n} value={n}>{n===0?"At reminder time":`${n} minutes before`}</option>)}</select></Field><button className="btn btn-outline" onClick={async()=>{if(!("Notification"in window)){toast("This browser does not support notifications.");return}const p=await Notification.requestPermission();toast(p==="granted"?"Browser notifications enabled.":"Notification permission was not granted.")}}>Request browser notification permission</button></section></div>}
function BackupPage({s,toast}:{s:State;toast:(v:string)=>void}){const [confirmRestore,setConfirmRestore]=useState(false);const download=()=>{const blob=new Blob([JSON.stringify(s,null,2)],{type:"application/json"});const url=URL.createObjectURL(blob);const a=document.createElement("a");a.href=url;a.download=`studora-backup-${todayYmd()}.json`;a.click();URL.revokeObjectURL(url);toast("Backup exported.")};const restore=async(file?:File)=>{if(!file)return;try{const parsed=JSON.parse(await file.text());if(!parsed||typeof parsed!=="object"||!Array.isArray(parsed.assignments)||!Array.isArray(parsed.classes))throw new Error("Invalid backup");if(!confirmRestore){setConfirmRestore(true);return}update(()=>({...defaultState,...parsed,version:1,settings:{...defaultState.settings,...parsed.settings,notif:{...defaultState.settings.notif,...parsed.settings?.notif}}}));setConfirmRestore(false);toast("Backup restored.");}catch{toast("That file doesn't look like a valid Studora backup.")}};return <div className="backup-grid"><section className="panel backup-card"><span className="backup-icon"><Download/></span><h2>Keep a copy of your data</h2><p>Export your classes, timetable, assignments, notes, goals, events and settings to a JSON backup file.</p><button className="btn btn-primary" onClick={download}><Download size={16}/> Export backup</button><small>Export regularly, especially before clearing browser data.</small></section><section className="panel backup-card"><span className="backup-icon"><Upload/></span><h2>Restore a backup</h2><p>Bring your saved Studora data back into this browser. Restoring replaces current data.</p><label className="btn btn-outline upload-btn"><Upload size={16}/> Choose backup file<input type="file" accept=".json,application/json" onChange={e=>void restore(e.target.files?.[0])}/></label>{confirmRestore&&<div className="restore-confirm"><p>This will replace the data currently in this browser. Continue only if you have exported a backup of the current data.</p><button className="btn btn-primary" onClick={()=>setConfirmRestore(false)}>Cancel restore</button><span className="muted-copy">Please reselect the backup file to confirm restoration.</span></div>}<small>Only restore a JSON file you trust.</small></section><section className="panel privacy-card"><span className="backup-icon"><Archive/></span><h2>Your data belongs to you</h2><p>Studora stores information in this browser on this device. There is no account or cloud sync in this version.</p><div className="privacy-stats"><span><strong>{s.classes.length}</strong> classes</span><span><strong>{s.assignments.length}</strong> assignments</span><span><strong>{s.notes.length}</strong> notes</span><span><strong>{s.goals.length}</strong> goals</span></div><button className="btn btn-danger-outline" onClick={()=>{if(confirm("This permanently clears Studora data from this browser. Export a backup first. Continue?")){localStorage.removeItem("studora-data-v1");location.reload()}}}><Trash2 size={16}/> Clear all local data</button></section></div>}

